CREATE VIEW "public"."usage_by_user_day" AS (select "conversation"."user_id", ("message"."created_at" at time zone 'UTC')::date as "day", "message"."model_id", count(*)::int as "answers", coalesce(sum("message"."tokens_in"), 0)::bigint as "tokens_in", coalesce(sum("message"."tokens_out"), 0)::bigint as "tokens_out", coalesce(sum("message"."cost_usd"), 0) as "cost_usd" from "message" inner join "conversation" on "conversation"."id" = "message"."conversation_id" where "message"."role" = 'assistant' group by "conversation"."user_id", 2, "message"."model_id");